package com.yeyamo_mobile.api.culture_service.domain;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="languages") public class Language{@Id@Column(length=35)private String code;@Column(nullable=false)private String name;@Column(name="native_name",nullable=false)private String nativeName;@Column(name="country_codes",nullable=false)private String countryCodes;@Column(name="writing_system")private String writingSystem;@Enumerated(EnumType.STRING)@Column(nullable=false)private LanguageStatus status;@Column(columnDefinition="TEXT")private String description;@Column(name="speaker_estimate")private Long speakerEstimate;@Column(nullable=false)private boolean verified;protected Language(){}public String getCode(){return code;}public String getName(){return name;}public String getNativeName(){return nativeName;}public List<String> getCountryCodes(){return Arrays.stream(countryCodes.split(",")).filter(s->!s.isBlank()).toList();}public String getWritingSystem(){return writingSystem;}public LanguageStatus getStatus(){return status;}public String getDescription(){return description;}public Long getSpeakerEstimate(){return speakerEstimate;}public boolean isVerified(){return verified;}public boolean available(){return status==LanguageStatus.ACTIVE||status==LanguageStatus.BETA;}}
